add_action('customize_register', function ($wp_customize) {
    $wp_customize->add_section('im_ficha_motel_colors', array(
        'title'    => 'Ficha Motel',
        'priority' => 35,
    ));

    $settings = array(
        'im_ficha_hero_bg' => array('label' => 'Fondo hero', 'default' => '#0f172a'),
        'im_ficha_primary'  => array('label' => 'Color primario', 'default' => '#2563eb'),
        'im_ficha_accent'   => array('label' => 'Color acento', 'default' => '#e94560'),
        'im_ficha_text'     => array('label' => 'Color texto', 'default' => '#111827'),
        'im_ficha_surface'  => array('label' => 'Fondo superficie', 'default' => '#ffffff'),
    );

    foreach ($settings as $id => $data) {
        $wp_customize->add_setting($id, array(
            'default'           => $data['default'],
            'sanitize_callback' => 'sanitize_hex_color',
            'transport'         => 'refresh',
        ));

        $wp_customize->add_control(new WP_Customize_Color_Control(
            $wp_customize,
            $id,
            array(
                'label'   => $data['label'],
                'section' => 'im_ficha_motel_colors',
            )
        ));
    }
});

