add_filter('the_content', function($content) {
    if (is_admin() || !is_singular('post') || has_category('blog')) {
        return $content;
    }

    if (strpos($content, 'id="mapa"') !== false) {
        return $content;
    }

    $post_id = get_the_ID();
    $direccion = get_post_meta($post_id, 'direccion', true);
    $comuna = get_post_meta($post_id, 'comuna', true);
    $ciudad = get_post_meta($post_id, 'ciudad', true);
    $geo_lat = get_post_meta($post_id, 'geo_lat', true);
    $geo_lng = get_post_meta($post_id, 'geo_lng', true);

    $direccion_txt = trim($direccion . ($comuna ? ', ' . $comuna : '') . ($ciudad ? ', ' . $ciudad : ''));
    if ($direccion_txt === '') {
        $direccion_txt = 'Consultar';
    } else {
        $direccion_txt .= ', Chile';
    }

    $query = ($geo_lat && $geo_lng)
        ? $geo_lat . ',' . $geo_lng
        : trim($direccion . ' ' . $comuna . ' ' . $ciudad . ' Chile');

    $iframe_src = 'https://www.google.com/maps?q=' . rawurlencode($query) . '&output=embed';

    $map = '\n<section id="mapa" class="ficha-section ficha-card">' .
        '<h2>Ubicacion</h2>' .
        '<p class="ficha-direccion">' . esc_html($direccion_txt) . '</p>' .
        '<div class="map-embed">' .
        '<iframe loading="lazy" src="' . esc_url($iframe_src) . '" width="100%" height="350" style="border:0; border-radius:16px;" allowfullscreen referrerpolicy="no-referrer-when-downgrade" title="Mapa de ' . esc_attr(get_the_title()) . '"></iframe>' .
        '</div>' .
    '</section>\n';

    return $content . $map;
}, 20);

