add_filter('the_content', function($content) {
    if (is_admin() || !is_singular('post') || has_category('blog')) {
        return $content;
    }

    $post_id = get_the_ID();
    $direccion = trim((string) get_post_meta($post_id, 'direccion', true));
    $comuna = trim((string) get_post_meta($post_id, 'comuna', true));
    $ciudad = trim((string) get_post_meta($post_id, 'ciudad', true));

    $direccion_txt = trim($direccion . ($comuna ? ', ' . $comuna : '') . ($ciudad ? ', ' . $ciudad : ''));
    if ($direccion_txt === '') {
        return $content;
    }
    $direccion_txt .= ', Chile';

    $map_query = rawurlencode(trim($direccion . ' ' . $comuna . ' ' . $ciudad . ' Chile'));
    $replacement = '<section id="mapa" class="ficha-section ficha-card">'
        . '<h2>Ubicacion</h2>'
        . '<p class="ficha-direccion">' . esc_html($direccion_txt) . '</p>'
        . '<div class="map-embed">'
        . '<iframe loading="lazy" src="https://www.google.com/maps?q=' . esc_attr($map_query) . '&output=embed" width="100%" height="350" style="border:0; border-radius:16px;" allowfullscreen referrerpolicy="no-referrer-when-downgrade" title="Mapa de ' . esc_attr(get_the_title()) . '"></iframe>'
        . '</div>'
        . '</section>';

    if (strpos($content, 'id="mapa"') !== false) {
        $content = preg_replace('/<section id="mapa" class="ficha-section ficha-card">.*?<\/section>/s', $replacement, $content, 1);
    } else {
        $content .= $replacement;
    }

    return $content;
}, 35);

