add_action('template_redirect', function () {
    if (is_admin() || is_singular('blog')) {
        return;
    }

    ob_start(function ($html) {
        $patterns = array(
            '/<aside class="motel-side">.*?<\/aside>/s',
            '/<aside class="sidebar-stack">.*?<\/aside>/s',
        );

        foreach ($patterns as $pattern) {
            $html = preg_replace($pattern, '', $html);
        }

        return $html;
    });
});

